export function taskLabel(name: string, completed: boolean): string {
  return (completed ? '[x] ' : '[ ] ') + name;
}

import assert from 'node:assert/strict';
import {describe, test} from 'node:test';
import {taskLabel} from '../src/labels.ts';

describe('taskLabel regression tests', () => {
  test('returns completed prefix [x] for completed task', () => {
    assert.equal(taskLabel('ship release', true), '[x] ship release');
  });

  test('returns incomplete prefix [ ] for incomplete task', () => {
    assert.equal(taskLabel('ship release', false), '[ ] ship release');
  });

  test('preserves the supplied name exactly with whitespace and symbols', () => {
    assert.equal(taskLabel('  feature #42 [WIP]  ', true), '[x]   feature #42 [WIP]  ');
    assert.equal(taskLabel('  feature #42 [WIP]  ', false), '[ ]   feature #42 [WIP]  ');
  });

  test('preserves empty string name', () => {
    assert.equal(taskLabel('', true), '[x] ');
    assert.equal(taskLabel('', false), '[ ] ');
  });
});

