import assert from 'node:assert/strict';
import {test} from 'node:test';
import {makeRouter} from '../src/app.ts';
import {unrelatedHelper, documentation} from '../src/routes/accounts.ts';
import {auditCallback} from '../src/routes/orders.ts';

test('router has expected routes in order', () => {
  const router = makeRouter();
  assert.equal(router.routes.length, 5);
  assert.deepEqual(
    router.routes.map(r => ({ method: r.method, path: r.path })),
    [
      { method: 'GET', path: '/accounts/:id' },
      { method: 'POST', path: '/accounts' },
      { method: 'GET', path: '/health' },
      { method: 'GET', path: '/orders/:id' },
      { method: 'DELETE', path: '/orders/:id' },
    ]
  );
});

test('GET /accounts/:id success and error forwarding', async () => {
  const router = makeRouter();
  const route = router.routes[0];
  const mockRes = { send: (val) => val };

  // Success
  let nextCalled = false;
  const result = await route.handler({ id: 'acc1' }, mockRes, () => { nextCalled = true; });
  assert.equal(result, 'account:acc1');
  assert.equal(nextCalled, false);

  // Error forwarding
  let forwardedError = null;
  await route.handler({ fail: true, id: 'acc1' }, mockRes, (err) => { forwardedError = err; });
  assert.ok(forwardedError instanceof Error);
  assert.equal(forwardedError.message, 'account read');
});

test('POST /accounts (named async function) success and error forwarding', async () => {
  const router = makeRouter();
  const route = router.routes[1];
  const mockRes = { send: (val) => val };

  // Success
  let nextCalled = false;
  const result = await route.handler({ id: 'acc2' }, mockRes, () => { nextCalled = true; });
  assert.equal(result, 'created:acc2');
  assert.equal(nextCalled, false);

  // Error forwarding
  let forwardedError = null;
  await route.handler({ fail: true, id: 'acc2' }, mockRes, (err) => { forwardedError = err; });
  assert.ok(forwardedError instanceof Error);
  assert.equal(forwardedError.message, 'account create');
});

test('GET /health synchronous route preserved', () => {
  const router = makeRouter();
  const route = router.routes[2];
  const mockRes = { send: (val) => val };
  let nextCalled = false;
  const result = route.handler({ id: 'any' }, mockRes, () => { nextCalled = true; });
  assert.equal(result, 'ok');
  assert.equal(nextCalled, false);
});

test('GET /orders/:id success and error forwarding', async () => {
  const router = makeRouter();
  const route = router.routes[3];
  const mockRes = { send: (val) => val };

  // Success
  let nextCalled = false;
  const result = await route.handler({ id: 'order1' }, mockRes, () => { nextCalled = true; });
  assert.equal(result, 'ORDER1');
  assert.equal(nextCalled, false);

  // Error forwarding
  let forwardedError = null;
  await route.handler({ fail: true, id: 'order1' }, mockRes, (err) => { forwardedError = err; });
  assert.ok(forwardedError instanceof Error);
  assert.equal(forwardedError.message, 'order read');
});

test('DELETE /orders/:id success and error forwarding', async () => {
  const router = makeRouter();
  const route = router.routes[4];
  const mockRes = { send: (val) => val };

  // Success
  let nextCalled = false;
  const result = await route.handler({ id: 'order2' }, mockRes, () => { nextCalled = true; });
  assert.equal(result, 'deleted:order2');
  assert.equal(nextCalled, false);

  // Error forwarding
  let forwardedError = null;
  await route.handler({ fail: true, id: 'order2' }, mockRes, (err) => { forwardedError = err; });
  assert.ok(forwardedError instanceof Error);
  assert.equal(forwardedError.message, 'order delete');
});

test('unrelated helpers and callbacks are not wrapped', async () => {
  await assert.rejects(async () => {
    await unrelatedHelper();
  }, { message: 'helper' });

  await assert.rejects(async () => {
    await auditCallback();
  }, { message: 'audit' });

  assert.equal(documentation, "router.get('/fake', async handler)");
