import assert from 'node:assert/strict';
import {describe, it} from 'node:test';
import {makeRouter} from '../src/app.ts';
import {unrelatedHelper} from '../src/routes/accounts.ts';
import {auditCallback} from '../src/routes/orders.ts';

describe('API routes regression tests', () => {
  const router = makeRouter();

  it('preserves registration order and route count', () => {
    assert.equal(router.routes.length, 5);
    assert.deepEqual(
      router.routes.map(r => ({method: r.method, path: r.path})),
      [
        {method: 'GET', path: '/accounts/:id'},
        {method: 'POST', path: '/accounts'},
        {method: 'GET', path: '/health'},
        {method: 'GET', path: '/orders/:id'},
        {method: 'DELETE', path: '/orders/:id'},
      ]
    );
  });

  describe('GET /accounts/:id', () => {
    const route = router.routes[0];

    it('handles successful requests and preserves response value', async () => {
      let nextCalled = false;
      const res = { send: (val) => `sent:${val}` };
      const next = (err) => { nextCalled = true; };

      const result = await route.handler({ id: '123' }, res, next);
      assert.equal(result, 'sent:account:123');
      assert.equal(nextCalled, false);
    });

    it('forwards failures to next when rejecting', async () => {
      let forwardedError = null;
      const res = { send: (val) => `sent:${val}` };
      const next = (err) => { forwardedError = err; };

      await route.handler({ id: '123', fail: true }, res, next);
      assert.ok(forwardedError instanceof Error);
      assert.equal(forwardedError.message, 'account read');
    });
  });

  describe('POST /accounts (named async function)', () => {
    const route = router.routes[1];

    it('handles successful requests and preserves response value', async () => {
      let nextCalled = false;
      const res = { send: (val) => `sent:${val}` };
      const next = (err) => { nextCalled = true; };

      const result = await route.handler({ id: '456' }, res, next);
      assert.equal(result, 'sent:created:456');
      assert.equal(nextCalled, false);
    });

    it('forwards failures to next when rejecting', async () => {
      let forwardedError = null;
      const res = { send: (val) => `sent:${val}` };
      const next = (err) => { forwardedError = err; };

      await route.handler({ id: '456', fail: true }, res, next);
      assert.ok(forwardedError instanceof Error);
      assert.equal(forwardedError.message, 'account create');
    });
  });

  describe('GET /health (synchronous route)', () => {
    const route = router.routes[2];

    it('handles synchronous request without wrapping', () => {
      let nextCalled = false;
      const res = { send: (val) => `sent:${val}` };
      const next = (err) => { nextCalled = true; };

      const result = route.handler({ id: '0' }, res, next);
      assert.equal(result, 'sent:ok');
      assert.equal(nextCalled, false);
    });
  });

  describe('GET /orders/:id', () => {
    const route = router.routes[3];

    it('handles successful requests and preserves response value', async () => {
      let nextCalled = false;
      const res = { send: (val) => `sent:${val}` };
      const next = (err) => { nextCalled = true; };

      const result = await route.handler({ id: 'ord-789' }, res, next);
      assert.equal(result, 'sent:ORD-789');
      assert.equal(nextCalled, false);
    });

    it('forwards failures to next when rejecting', async () => {
      let forwardedError = null;
      const res = { send: (val) => `sent:${val}` };
      const next = (err) => { forwardedError = err; };

      await route.handler({ id: 'ord-789', fail: true }, res, next);
      assert.ok(forwardedError instanceof Error);
      assert.equal(forwardedError.message, 'order read');
    });
  });

  describe('DELETE /orders/:id', () => {
    const route = router.routes[4];

    it('handles successful requests and preserves response value', async () => {
      let nextCalled = false;
      const res = { send: (val) => `sent:${val}` };
      const next = (err) => { nextCalled = true; };

      const result = await route.handler({ id: 'ord-999' }, res, next);
      assert.equal(result, 'sent:deleted:ord-999');
      assert.equal(nextCalled, false);
    });

    it('forwards failures to next when rejecting', async () => {
      let forwardedError = null;
      const res = { send: (val) => `sent:${val}` };
      const next = (err) => { forwardedError = err; };

      await route.handler({ id: 'ord-999', fail: true }, res, next);
      assert.ok(forwardedError instanceof Error);
      assert.equal(forwardedError.message, 'order delete');
    });
  });

  describe('unrelated callbacks and helpers remain unwrapped', () => {
    it('unrelatedHelper throws directly instead of passing to next', async () => {
      await assert.rejects(async () => {
        await unrelatedHelper();
      }, { message: 'helper' });
    });

    it('auditCallback throws directly instead of passing to next', async () => {
      await assert.rejects(async () => {
        await auditCallback();
      }, { message: 'audit' });
    });
  });
});

