import assert from 'node:assert/strict';
import {describe, test} from 'node:test';
import {createContext, forkContext} from '../src/context-factory.ts';
import {describeJob} from '../src/jobs.ts';
import {auditLabel} from '../src/job-types.ts';
import {traceSummary} from '../src/plugins/index.ts';
import {handle} from '../src/app.ts';

describe('RequestContext rename and end-to-end propagation', () => {
  test('RequestContext has traceId and no requestId compatibility member', () => {
    const context = createContext('trace-001', 'user-001');
    assert.equal(context.traceId, 'trace-001');
    assert.equal(context.userId, 'user-001');
    assert.equal('requestId' in context, false);
    assert.equal(context.requestId, undefined);
  });

  test('forkContext non-mutation and suffix behavior', () => {
    const parent = createContext('trace-root', 'user-root');
    const child = forkContext(parent, 'child-step');

    assert.equal(parent.traceId, 'trace-root');
    assert.equal('requestId' in parent, false);

    assert.equal(child.traceId, 'trace-root/child-step');
    assert.equal(child.userId, 'user-root');
    assert.equal('requestId' in child, false);
    assert.notEqual(parent, child);
  });

  test('end-to-end handle propagation and output wire keys', () => {
    const job = {requestId: 'job-alpha-42', name: 'process-events'};
    const result = handle('trace-req-777', 'alice', job);

    // Root context contains traceId
    assert.equal(result.context.traceId, 'trace-req-777');
    assert.equal(result.context.userId, 'alice');
    assert.equal('requestId' in result.context, false);

    // Middleware headers wire traceId to x-request-id
    assert.equal(result.headers['x-request-id'], 'trace-req-777');

    // Logging wire fields keep requestId key mapped to trace identifier
    assert.equal(result.logs.requestId, 'trace-req-777');
    assert.equal(result.logs.userId, 'alice');

    // Response wire envelope keeps requestId key mapped to trace identifier
    assert.equal(result.body.requestId, 'trace-req-777');

    // Worker stage received forked traceId with suffix
    assert.equal(result.body.payload.trace, 'trace-req-777/worker');
  });

  test('preserves unrelated Job.requestId and audit values', () => {
    const job = {requestId: 'job-unique-99', name: 'audit-task'};
    const context = createContext('trace-audit', 'auditor');

    assert.equal(auditLabel(job.requestId), 'job:job-unique-99');

    const jobDescription = describeJob(job, context);
    assert.equal(jobDescription.requestId, 'job-unique-99');
    assert.equal(jobDescription.trace, 'trace-audit');
    assert.equal(jobDescription.audit, 'job:job-unique-99');
    assert.equal(jobDescription.name, 'audit-task');

    const result = handle('trace-flow', 'bob', job);
    assert.equal(result.body.payload.requestId, 'job-unique-99');
    assert.equal(result.body.payload.audit, 'job:job-unique-99');
    assert.equal(result.body.payload.name, 'audit-task');
  });

  test('traceSummary and plugin consumers receive traceId', () => {
    const context = createContext('trace-plugin-test', 'plugin-user');
    const summary = traceSummary(context);

    assert.equal(summary.length, 8);
    for (let i = 0; i < 8; i++) {
      assert.equal(summary[i].requestId, 'trace-plugin-test');
      assert.equal(summary[i].tag, `plugin${i}`);
      assert.equal(summary[i].user, 'plugin-user');
    }
  });
});

