import assert from 'node:assert/strict';
import {test} from 'node:test';
import {handle} from '../src/app.ts';
import {createContext, forkContext} from '../src/context-factory.ts';
import {describeJob} from '../src/jobs.ts';
import {auditLabel} from '../src/job-types.ts';
import {traceSummary} from '../src/plugins/index.ts';
import {record0} from '../src/catalog/record0.ts';

test('end-to-end traceId propagation through handle', () => {
  const job = {requestId: 'job-42', name: 'process-data'};
  const result = handle('trace-root-100', 'alice', job);

  // Context contains traceId and does NOT contain requestId
  assert.equal(result.context.traceId, 'trace-root-100');
  assert.equal(result.context.userId, 'alice');
  assert.equal('requestId' in result.context, false);

  // Headers retain wire key 'x-request-id' with traceId value
  assert.equal(result.headers['x-request-id'], 'trace-root-100');

  // Logs retain output key 'requestId' with traceId value
  assert.deepEqual(result.logs, {
    requestId: 'trace-root-100',
    userId: 'alice',
  });

  // Body retains output key 'requestId' with traceId value
  assert.equal(result.body.requestId, 'trace-root-100');

  // Worker stage received forked context with '/worker' suffix
  assert.equal(result.body.payload.trace, 'trace-root-100/worker');

  // Non-mutation behavior: original context traceId was unchanged by worker fork
  assert.equal(result.context.traceId, 'trace-root-100');
});

test('unrelated Job identifier is preserved and distinguished from trace identifier', () => {
  const job = {requestId: 'job-unique-999', name: 'analytics-sync'};
  const context = createContext('trace-stage-0', 'bob');

  assert.equal(job.requestId, 'job-unique-999');
  assert.equal(auditLabel(job.requestId), 'job:job-unique-999');

  const jobDesc = describeJob(job, context);
  assert.equal(jobDesc.requestId, 'job-unique-999');
  assert.equal(jobDesc.trace, 'trace-stage-0');
  assert.equal(jobDesc.audit, 'job:job-unique-999');
  assert.equal(jobDesc.name, 'analytics-sync');
});

test('forkContext produces new context with suffixed traceId without mutating original', () => {
  const original = createContext('trace-base', 'charlie');
  const forked = forkContext(original, 'subtask');

  assert.equal(original.traceId, 'trace-base');
  assert.equal(forked.traceId, 'trace-base/subtask');
  assert.equal(forked.userId, 'charlie');
  assert.notEqual(original, forked);
});

test('traceSummary in plugins preserves traceId across all plugins', () => {
  const context = createContext('trace-plug-1', 'david');
  const summary = traceSummary(context);

  assert.equal(summary.length, 8);
  for (let i = 0; i < 8; i++) {
    assert.deepEqual(summary[i], {
      requestId: 'trace-plug-1',
      tag: `plugin${i}`,
      user: 'david',
    });
  }
});

test('catalog modules preserve independent RequestContext and requestId', () => {
  const catResult = record0({requestId: 'cat-item-1', category: 'electronics'});
  assert.equal(catResult.requestId, 'cat-item-1');
  assert.equal(catResult.category, 'electronics');
  assert.equal(catResult.label, 'record0:cat-item-1');
});

