export function taskLabel(name: string, completed: boolean): string {
  return (completed ? '[x] ' : '[ ] ') + name;
}

import assert from 'node:assert/strict';
import { describe, test } from 'node:test';
import { taskLabel } from '../src/labels.ts';

describe('taskLabel regression tests', () => {
  test('completed task prefixes [x] and preserves name', () => {
    assert.equal(taskLabel('publish', true), '[x] publish');
    assert.equal(taskLabel('draft', true), '[x] draft');
  });

  test('incomplete task keeps [ ] prefix and preserves name', () => {
    assert.equal(taskLabel('draft', false), '[ ] draft');
    assert.equal(taskLabel('review', false), '[ ] review');
  });

  test('preserves exact spacing and special characters', () => {
    assert.equal(taskLabel('', true), '[x] ');
    assert.equal(taskLabel('', false), '[ ] ');
    assert.equal(taskLabel('  indented  ', true), '[x]   indented  ');
    assert.equal(taskLabel('  indented  ', false), '[ ]   indented  ');
    assert.equal(taskLabel('Task with [brackets] and emoji 🚀', true), '[x] Task with [brackets] and emoji 🚀');
  });
});

