import {Router} from '../framework/router.ts';
export function registerAccounts(router: Router) {
  router.get('/accounts/:id', withErrors(async (req, res) => {
    if(req.fail) throw new Error('account read');
    return res.send('account:'+req.id);
  }));
  router.post('/accounts', withErrors(async function createAccount(req, res) {
    if(req.fail) throw new Error('account create');
    return res.send('created:'+req.id);
  }));
  router.get('/health', (_req,res) => res.send('ok'));
}
export const documentation = "router.get('/fake', async handler)";
export async function unrelatedHelper() { throw new Error('helper'); }

import {withErrors} from '../framework/errors.ts';
import {Router} from '../framework/router.ts';
const audit = { get(_name: string, callback: () => Promise<string>) { return callback; } };
export const auditCallback = audit.get('orders', async () => { throw new Error('audit'); });
export function registerOrders(router: Router) {
  router.get('/orders/:id', withErrors(async (req,res) => {
    const values = await Promise.all([req.id].map(async value => value.toUpperCase()));
    if(req.fail) throw new Error('order read');
    return res.send(values[0]);
  }));
  router.delete('/orders/:id', withErrors(async (req,res) => {
    if(req.fail) throw new Error('order delete');
    return res.send('deleted:'+req.id);
  }));
}

import assert from 'node:assert/strict';
import {describe, test} from 'node:test';
import {makeRouter} from '../src/app.ts';
import {documentation, unrelatedHelper} from '../src/routes/accounts.ts';
import {auditCallback} from '../src/routes/orders.ts';

describe('Route registration order and preservation', () => {
  test('registration order and route paths/methods match specification', () => {
    const router = makeRouter();
    assert.equal(router.routes.length, 5);

    const expected = [
      {method: 'GET', path: '/accounts/:id'},
      {method: 'POST', path: '/accounts'},
      {method: 'GET', path: '/health'},
      {method: 'GET', path: '/orders/:id'},
      {method: 'DELETE', path: '/orders/:id'},
    ];

    for (let i = 0; i < expected.length; i++) {
      assert.equal(router.routes[i].method, expected[i].method);
      assert.equal(router.routes[i].path, expected[i].path);
    }
  });

  test('synchronous health route is preserved and returns response synchronously', () => {
    const router = makeRouter();
    const healthRoute = router.routes.find(r => r.path === '/health');
    assert.ok(healthRoute);

    const req = {id: 'test'};
    const res = {send: (val) => val};
    let nextCalled = false;
    const next = () => { nextCalled = true; };

    const result = healthRoute.handler(req, res, next);
    assert.equal(result, 'ok');
    assert.equal(nextCalled, false);
    // Ensure synchronous handler did not return a promise
    assert.notEqual(result instanceof Promise, true);
  });
});

describe('Successful request handling on wrapped async handlers', () => {
  function createMocks(reqData) {
    let sent = null;
    let nextError = null;
    const req = reqData;
    const res = {
      send(val) {
        sent = val;
        return val;
      },
    };
    const next = (err) => {
      nextError = err;
    };
    return {
      req,
      res,
      next,
      getSent: () => sent,
      getNextError: () => nextError,
    };
  }

  test('GET /accounts/:id returns account response value', async () => {
    const router = makeRouter();
    const route = router.routes[0];
    const {req, res, next, getSent, getNextError} = createMocks({id: '42'});

    const result = await route.handler(req, res, next);
    assert.equal(result, 'account:42');
    assert.equal(getSent(), 'account:42');
    assert.equal(getNextError(), null);
  });

  test('POST /accounts (named async function) returns created response value', async () => {
    const router = makeRouter();
    const route = router.routes[1];
    const {req, res, next, getSent, getNextError} = createMocks({id: '99'});

    const result = await route.handler(req, res, next);
    assert.equal(result, 'created:99');
    assert.equal(getSent(), 'created:99');
    assert.equal(getNextError(), null);
  });

  test('GET /orders/:id returns uppercase id order response value', async () => {
    const router = makeRouter();
    const route = router.routes[3];
    const {req, res, next, getSent, getNextError} = createMocks({id: 'ord-100'});

    const result = await route.handler(req, res, next);
    assert.equal(result, 'ORD-100');
    assert.equal(getSent(), 'ORD-100');
    assert.equal(getNextError(), null);
  });

  test('DELETE /orders/:id returns deleted response value', async () => {
    const router = makeRouter();
    const route = router.routes[4];
    const {req, res, next, getSent, getNextError} = createMocks({id: 'ord-200'});

    const result = await route.handler(req, res, next);
