    assert.equal(getSent(), 'deleted:ord-200');
    assert.equal(getNextError(), null);
  });
});

describe('Error forwarding to next on wrapped async handlers', () => {
  function createMocks(reqData) {
    let sent = null;
    let nextError = null;
    const req = reqData;
    const res = {
      send(val) {
        sent = val;
        return val;
      },
    };
    const next = (err) => {
      nextError = err;
    };
    return {
      req,
      res,
      next,
      getSent: () => sent,
      getNextError: () => nextError,
    };
  }

  test('GET /accounts/:id forwards error to next when failure occurs', async () => {
    const router = makeRouter();
    const route = router.routes[0];
    const {req, res, next, getSent, getNextError} = createMocks({id: '42', fail: true});

    await route.handler(req, res, next);
    assert.equal(getSent(), null);
    assert.ok(getNextError() instanceof Error);
    assert.equal(getNextError().message, 'account read');
  });

  test('POST /accounts forwards error to next when failure occurs', async () => {
    const router = makeRouter();
    const route = router.routes[1];
    const {req, res, next, getSent, getNextError} = createMocks({id: '99', fail: true});

    await route.handler(req, res, next);
    assert.equal(getSent(), null);
    assert.ok(getNextError() instanceof Error);
    assert.equal(getNextError().message, 'account create');
  });

  test('GET /orders/:id forwards error to next when failure occurs', async () => {
    const router = makeRouter();
    const route = router.routes[3];
    const {req, res, next, getSent, getNextError} = createMocks({id: 'ord-100', fail: true});

    await route.handler(req, res, next);
    assert.equal(getSent(), null);
    assert.ok(getNextError() instanceof Error);
    assert.equal(getNextError().message, 'order read');
  });

  test('DELETE /orders/:id forwards error to next when failure occurs', async () => {
    const router = makeRouter();
    const route = router.routes[4];
    const {req, res, next, getSent, getNextError} = createMocks({id: 'ord-200', fail: true});

    await route.handler(req, res, next);
    assert.equal(getSent(), null);
    assert.ok(getNextError() instanceof Error);
    assert.equal(getNextError().message, 'order delete');
  });
});

describe('Unrelated exports and functions are untouched', () => {
  test('documentation export remains unchanged', () => {
    assert.equal(documentation, "router.get('/fake', async handler)");
  });

  test('unrelatedHelper remains ordinary async function that rejects without next forwarding', async () => {
    await assert.rejects(async () => {
      await unrelatedHelper();
    }, {
      name: 'Error',
      message: 'helper',
    });
  });

  test('auditCallback remains unmodified async callback that rejects without next forwarding', async () => {
    await assert.rejects(async () => {
      await auditCallback();
    }, {
      name: 'Error',
      message: 'audit',
    });
  });
});

