import assert from 'node:assert/strict';
import {describe, test} from 'node:test';
import {makeRouter} from '../src/app.ts';
import {documentation, unrelatedHelper} from '../src/routes/accounts.ts';
import {auditCallback} from '../src/routes/orders.ts';

function createMockRes() {
  let sent;
  return {
    res: {
      send(val) {
        sent = val;
        return val;
      }
    },
    getSent: () => sent
  };
}

describe('Router registration and order', () => {
  test('routes preserve exact registration order and methods', () => {
    const router = makeRouter();
    assert.equal(router.routes.length, 5);

    assert.equal(router.routes[0].method, 'GET');
    assert.equal(router.routes[0].path, '/accounts/:id');

    assert.equal(router.routes[1].method, 'POST');
    assert.equal(router.routes[1].path, '/accounts');

    assert.equal(router.routes[2].method, 'GET');
    assert.equal(router.routes[2].path, '/health');

    assert.equal(router.routes[3].method, 'GET');
    assert.equal(router.routes[3].path, '/orders/:id');

    assert.equal(router.routes[4].method, 'DELETE');
    assert.equal(router.routes[4].path, '/orders/:id');
  });
});

describe('Successful route handling', () => {
  test('GET /accounts/:id succeeds and sends response value', async () => {
    const router = makeRouter();
    const route = router.routes[0];
    const {res, getSent} = createMockRes();
    let nextCalled = false;
    const next = () => { nextCalled = true; };

    const result = await route.handler({id: 'acc-1'}, res, next);
    assert.equal(result, 'account:acc-1');
    assert.equal(getSent(), 'account:acc-1');
    assert.equal(nextCalled, false);
  });

  test('POST /accounts (named async function) succeeds and sends response value', async () => {
    const router = makeRouter();
    const route = router.routes[1];
    const {res, getSent} = createMockRes();
    let nextCalled = false;
    const next = () => { nextCalled = true; };

    const result = await route.handler({id: 'acc-2'}, res, next);
    assert.equal(result, 'created:acc-2');
    assert.equal(getSent(), 'created:acc-2');
    assert.equal(nextCalled, false);
  });

  test('GET /health preserves synchronous handling', () => {
    const router = makeRouter();
    const route = router.routes[2];
    const {res, getSent} = createMockRes();
    let nextCalled = false;
    const next = () => { nextCalled = true; };

    const result = route.handler({id: ''}, res, next);
    assert.equal(result, 'ok');
    assert.equal(getSent(), 'ok');
    assert.equal(nextCalled, false);
  });

  test('GET /orders/:id succeeds with async transformation and sends response value', async () => {
    const router = makeRouter();
    const route = router.routes[3];
    const {res, getSent} = createMockRes();
    let nextCalled = false;
    const next = () => { nextCalled = true; };

    const result = await route.handler({id: 'order-1'}, res, next);
    assert.equal(result, 'ORDER-1');
    assert.equal(getSent(), 'ORDER-1');
    assert.equal(nextCalled, false);
  });

  test('DELETE /orders/:id succeeds and sends response value', async () => {
    const router = makeRouter();
    const route = router.routes[4];
    const {res, getSent} = createMockRes();
    let nextCalled = false;
    const next = () => { nextCalled = true; };

    const result = await route.handler({id: 'order-2'}, res, next);
    assert.equal(result, 'deleted:order-2');
    assert.equal(getSent(), 'deleted:order-2');
    assert.equal(nextCalled, false);
  });
});

describe('Error forwarding via next', () => {
  test('GET /accounts/:id forwards error to next when handler throws', async () => {
    const router = makeRouter();
    const route = router.routes[0];
    const {res} = createMockRes();
    let forwardedError = null;
    const next = (err) => { forwardedError = err; };

    await route.handler({id: 'acc-fail', fail: true}, res, next);
    assert.ok(forwardedError instanceof Error);
    assert.equal(forwardedError.message, 'account read');
  });

  test('POST /accounts forwards error to next when handler throws', async () => {
    const router = makeRouter();
    const route = router.routes[1];
    const {res} = createMockRes();
    let forwardedError = null;
    const next = (err) => { forwardedError = err; };

    await route.handler({id: 'acc-fail', fail: true}, res, next);
    assert.ok(forwardedError instanceof Error);
    assert.equal(forwardedError.message, 'account create');
  });

  test('GET /orders/:id forwards error to next when handler throws', async () => {
    const router = makeRouter();
    const route = router.routes[3];
    const {res} = createMockRes();
    let forwardedError = null;
    const next = (err) => { forwardedError = err; };

    await route.handler({id: 'order-fail', fail: true}, res, next);
    assert.ok(forwardedError instanceof Error);
    assert.equal(forwardedError.message, 'order read');
  });

  test('DELETE /orders/:id forwards error to next when handler throws', async () => {
    const router = makeRouter();
    const route = router.routes[4];
    const {res} = createMockRes();
    let forwardedError = null;
    const next = (err) => { forwardedError = err; };

    await route.handler({id: 'order-fail', fail: true}, res, next);
    assert.ok(forwardedError instanceof Error);
    assert.equal(forwardedError.message, 'order delete');
  });
});

describe('Unrelated async functions, callbacks and documentation', () => {
  test('documentation string is preserved unmodified', () => {
    assert.equal(documentation, "router.get('/fake', async handler)");
  });

  test('unrelatedHelper remains ordinary async function and rejects', async () => {
    await assert.rejects(async () => {
      await unrelatedHelper();
    }, {
      name: 'Error',
      message: 'helper'
    });
  });

  test('auditCallback is not wrapped with withErrors and rejects directly', async () => {
    await assert.rejects(async () => {
      await auditCallback();
    }, {
      name: 'Error',
      message: 'audit'
    });
  });
});

