import assert from 'node:assert/strict';
import {describe, test} from 'node:test';
import {handle} from '../src/app.ts';
import {createContext, forkContext} from '../src/context-factory.ts';
import {describeJob} from '../src/jobs.ts';
import {work} from '../src/worker.ts';
import {traceSummary} from '../src/plugins/index.ts';
import {record0, audit0} from '../src/catalog/record0.ts';

describe('RequestContext traceId migration and propagation', () => {
  test('RequestContext has traceId and no requestId property', () => {
    const ctx = createContext('trace-123', 'user-456');
    assert.equal(ctx.traceId, 'trace-123');
    assert.equal(ctx.userId, 'user-456');
    assert.equal('requestId' in ctx, false);
    assert.equal(ctx.requestId, undefined);
  });

  test('forkContext produces non-mutated context with suffixed traceId and no requestId', () => {
    const parent = createContext('trace-root', 'user-1');
    const child = forkContext(parent, 'child');

    assert.equal(parent.traceId, 'trace-root');
    assert.equal(child.traceId, 'trace-root/child');
    assert.equal(child.userId, 'user-1');
    assert.equal('requestId' in child, false);
  });

  test('end-to-end propagation through app handle', () => {
    const job = { requestId: 'job-999', name: 'data-sync' };
    const result = handle('trace-abc', 'user-xyz', job);

    // Context field rename
    assert.equal(result.context.traceId, 'trace-abc');
    assert.equal('requestId' in result.context, false);

    // Headers preserve wire key with traceId value
    assert.equal(result.headers['x-request-id'], 'trace-abc');

    // Logs preserve wire key with traceId value
    assert.equal(result.logs.requestId, 'trace-abc');
    assert.equal(result.logs.userId, 'user-xyz');

    // Body preserves wire key with traceId value
    assert.equal(result.body.requestId, 'trace-abc');

    // Worker payload verifies trace propagation through forkContext
    assert.equal(result.body.payload.trace, 'trace-abc/worker');

    // Unrelated Job.requestId is preserved and distinct from context traceId
    assert.equal(result.body.payload.requestId, 'job-999');
    assert.equal(result.body.payload.name, 'data-sync');
    assert.equal(result.body.payload.audit, 'job:job-999');
  });

  test('unrelated Job identifier and auditLabel in describeJob and work', () => {
    const ctx = createContext('trace-test', 'user-test');
    const job = { requestId: 'job-unique-id', name: 'background-task' };

    const jobDesc = describeJob(job, ctx);
    assert.equal(jobDesc.requestId, 'job-unique-id');
    assert.equal(jobDesc.trace, 'trace-test');
    assert.equal(jobDesc.audit, 'job:job-unique-id');
    assert.equal(jobDesc.name, 'background-task');

    const workResult = work(ctx, job);
    assert.equal(workResult.requestId, 'job-unique-id');
    assert.equal(workResult.trace, 'trace-test/worker');
    assert.equal(workResult.audit, 'job:job-unique-id');
    assert.equal(workResult.name, 'background-task');
  });

  test('traceSummary in src/plugins/index.ts and plugin consumers preserve output format', () => {
    const ctx = createContext('trace-plugins', 'user-plugins');
    const summary = traceSummary(ctx);

    assert.equal(summary.length, 8);
    for (let i = 0; i < 8; i++) {
      assert.deepEqual(summary[i], {
        requestId: 'trace-plugins',
        tag: `plugin${i}`,
        user: 'user-plugins',
      });
    }
  });

  test('src/catalog RequestContext and requestId are preserved', () => {
    const catalogCtx = { requestId: 'cat-777', category: 'books' };
    const catalogResult = record0(catalogCtx);

    assert.equal(catalogResult.requestId, 'cat-777');
    assert.equal(catalogResult.category, 'books');
    assert.equal(catalogResult.label, 'record0:cat-777');
    assert.equal(audit0('cat-777'), 'audit0:cat-777');
  });
});

