import assert from 'node:assert/strict';
import {describe, test} from 'node:test';
import {handle} from '../src/app.ts';
import {createContext, forkContext} from '../src/context-factory.ts';
import {describeJob} from '../src/jobs.ts';
import {work} from '../src/worker.ts';
import {traceSummary} from '../src/plugins/index.ts';
import {record0} from '../src/catalog/record0.ts';

describe('RequestContext rename regression tests', () => {
  test('end-to-end propagation through handle', () => {
    const trace = 'trace-alpha-123';
    const user = 'user-test-456';
    const job = {requestId: 'job-req-789', name: 'process-data'};

    const result = handle(trace, user, job);

    // Context field rename: traceId present, requestId absent on RequestContext
    assert.equal(result.context.traceId, trace);
    assert.equal('requestId' in result.context, false);
    assert.equal(result.context.userId, user);

    // Headers propagate traceId as wire key x-request-id
    assert.equal(result.headers['x-request-id'], trace);

    // Logs retain wire key requestId with trace value and user
    assert.equal(result.logs.requestId, trace);
    assert.equal(result.logs.userId, user);

    // Response body retains wire key requestId with trace value
    assert.equal(result.body.requestId, trace);

    // Response payload preserves unrelated Job.requestId, forked traceId, and audit
    assert.equal(result.body.payload.requestId, 'job-req-789');
    assert.equal(result.body.payload.trace, `${trace}/worker`);
    assert.equal(result.body.payload.audit, 'job:job-req-789');
    assert.equal(result.body.payload.name, 'process-data');
  });

  test('unrelated Job identifier is preserved across job handling', () => {
    const job = {requestId: 'job-standalone-99', name: 'batch-task'};
    const context = createContext('ctx-trace-001', 'user-001');

    // describeJob keeps job.requestId distinct from context.traceId
    const description = describeJob(job, context);
    assert.equal(description.requestId, 'job-standalone-99');
    assert.equal(description.trace, 'ctx-trace-001');
    assert.equal(description.audit, 'job:job-standalone-99');
    assert.equal(description.name, 'batch-task');

    // work forks context and retains job.requestId
    const workResult = work(context, job);
    assert.equal(workResult.requestId, 'job-standalone-99');
    assert.equal(workResult.trace, 'ctx-trace-001/worker');
    assert.equal(workResult.audit, 'job:job-standalone-99');
    assert.equal(workResult.name, 'batch-task');
  });

  test('context-factory non-mutation and forkContext suffix behavior', () => {
    const initial = createContext('trace-root', 'user-1');
    assert.equal(initial.traceId, 'trace-root');
    assert.equal('requestId' in initial, false);

    const forked1 = forkContext(initial, 'sub1');
    assert.equal(initial.traceId, 'trace-root', 'original context must not be mutated');
    assert.equal(forked1.traceId, 'trace-root/sub1');
    assert.equal(forked1.userId, 'user-1');
    assert.equal('requestId' in forked1, false);

    const forked2 = forkContext(forked1, 'sub2');
    assert.equal(forked1.traceId, 'trace-root/sub1', 'forked1 must not be mutated');
    assert.equal(forked2.traceId, 'trace-root/sub1/sub2');
  });

  test('traceSummary and plugin propagation', () => {
    const context = createContext('plugin-trace', 'plugin-user');
    const summaries = traceSummary(context);

    assert.equal(summaries.length, 8);
    summaries.forEach((summary, idx) => {
      assert.equal(summary.requestId, 'plugin-trace');
      assert.equal(summary.tag, `plugin${idx}`);
      assert.equal(summary.user, 'plugin-user');
    });
  });

  test('unrelated catalog RequestContext preserves requestId API', () => {
    const catalogCtx = {requestId: 'cat-123', category: 'hardware'};
    const out = record0(catalogCtx);
    assert.equal(out.requestId, 'cat-123');
    assert.equal(out.category, 'hardware');
    assert.equal(out.label, 'record0:cat-123');
  });
});
